import Foundation
import DirectionCore

public struct ToolDefinition: Codable, Sendable {
    public var name: String
    public var description: String
    public var inputSchema: JSONValue
    public var readOnly: Bool
}

public enum ToolCatalog {
    static let string = JSONValue.object(["type": .string("string")])
    static let number = JSONValue.object(["type": .string("number")])
    static let integer = JSONValue.object(["type": .string("integer"), "minimum": .number(0)])
    static let bool = JSONValue.object(["type": .string("boolean")])
    static let object = JSONValue.object(["type": .string("object")])
    static func record(_ properties: [String: JSONValue], required: [String] = []) -> JSONValue { .object(["type": .string("object"), "properties": .object(properties), "required": .array(required.map(JSONValue.string)), "additionalProperties": .bool(false)]) }
    static func list(_ item: JSONValue) -> JSONValue { .object(["type": .string("array"), "items": item]) }
    /// An object keyed by ids the caller chooses (a note's id), each value of one shape.
    static func map(_ value: JSONValue) -> JSONValue { .object(["type": .string("object"), "additionalProperties": value]) }
    static let fraction = JSONValue.object(["type": .string("number"), "minimum": .number(0), "maximum": .number(1)])
    static let time = record(["value": integer, "timescale": .object(["type": .string("integer"), "minimum": .number(1)])], required: ["value", "timescale"])
    private static let range = record(["start": time, "duration": time], required: ["start", "duration"])
    private static let grade = record(["exposure": number, "contrast": number, "saturation": number, "temperature": number, "tint": number], required: ["exposure", "contrast", "saturation", "temperature", "tint"])
    private static let framing = record(["fit": bool, "scale": number, "offsetX": number, "offsetY": number, "opacity": number], required: ["fit", "scale", "offsetX", "offsetY", "opacity"])
    private static let effects = record(["highPassHz": number, "bassDB": number, "trebleDB": number, "compressor": bool, "thresholdDB": number, "limiter": bool])
    /// Only what changes: the rest stays as the track or clip has it.
    private static let audio = noted(record(["muted": bool, "gainDB": number, "fadeIn": number, "fadeOut": number, "effects": effects]), "audio: what to change on the track, like {\"muted\": true} or {\"gainDB\": -3, \"effects\": {\"highPassHz\": 80}}; the rest stays as it is.")
    // An edit function: {op, …its arguments}. Arguments are checked per operation by Direction, so errors
    // come back as {index, code, message}; the schema only documents them. Times are seconds or {value,timescale}.
    private static let signed = JSONValue.object(["type": .string("integer")])
    static func described(_ text: String) -> JSONValue { .object(["description": .string(text)]) }
    /// A schema with words on it, for a shape the field name doesn't explain.
    static func noted(_ schema: JSONValue, _ text: String) -> JSONValue { guard case .object(var o) = schema else { return schema }; o["description"] = .string(text); return .object(o) }
    /// An argument that takes more than one shape, each typed (Codex drops a field with no type to {}).
    static func either(_ shapes: [JSONValue], _ text: String) -> JSONValue { .object(["anyOf": .array(shapes), "description": .string(text)]) }
    /// A time: seconds, or {value, timescale}.
    static let moment = either([number, time], "Seconds, like 4.2, or {value, timescale}.")
    /// A moment of the music: its bar, a beat of the bar, or its beat; clip names the music when more than one song plays.
    static let bars = record(["bar": integer, "beat": integer, "clip": string])
    /// A stretch: {start, end}, or {start, duration}, each a time.
    static func span(_ text: String) -> JSONValue { noted(record(["start": moment, "end": moment, "duration": moment], required: ["start"]), text) }
    private static let operation: JSONValue = .object(["type": .string("object"), "description": .string("One edit function: {\"op\": name, …arguments}. direction_edit_catalog lists every op with its arguments."), "properties": .object([
        "op": .object(["type": .string("string"), "description": .string("insert overwrite removeRange remove move split trim roll slip slide splitEdit replaceTake removeWords tightenPauses speed freeze · reframe balance matchBalance cameraLUT addEffect setEffect removeEffect transition removeTransition · cutaway placeGraphic placeMade · gain fade duck placeMusic parts audio · loudness captions credits · format duplicateSequence")]),
        "type": .object(["type": .string("string"), "description": .string("transition: dissolve, dipToBlack or dipToWhite. (Batches from before edit functions named the operation here.)")]),
        "note": integer, "assetID": string, "clipID": string, "withAssetID": string, "toClipID": string, "madeID": string, "graphic": string, "effectID": string, "effect": string, "target": string, "track": string, "under": string, "editPoint": string, "cover": string, "lut": string, "text": string,
        "edge": strings(["head", "tail"]), "lead": strings(["sound", "picture"]), "snap": strings(["blink", "action", "pause"]), "alignOn": strings(["words", "head", "tail"]), "follow": strings(["face", "subject", "screen"]), "keepIn": strings(["thirds", "center"]),
        "frames": signed, "in": integer, "out": integer, "layer": integer, "audioTrackID": integer, "width": integer, "height": integer,
        "ripple": bool, "aboveLook": bool, "rate": number, "speed": number, "seconds": number, "scale": number, "x": number, "y": number, "exposure": number, "contrast": number, "saturation": number, "temperature": number, "tint": number, "longerThan": number, "dB": number, "attack": number, "release": number, "lufs": number, "truePeak": number, "wordsAtATime": integer,
        "wordIDs": list(string), "params": object, "keys": object, "grade": grade, "framing": framing, "audio": audio, "frameRate": record(["numerator": integer, "denominator": integer], required: ["numerator", "denominator"]),
        "at": either([number, time, Self.bars], "Cut seconds; or where a bar of the music in the cut plays: {bar: 9}, {bar: 9, beat: 3}, {beat: 33}, with clip when more than one song plays."), "range": span("{start, end} in cut seconds."), "sourceRange": span("{start, end} in the take's seconds."),
        "to": either([number, record(["at": number, "before": string, "after": string, "track": string])], "move: {at} or {before: clip} or {after: clip}, with track to change it. tightenPauses: seconds each pause becomes."), "endOn": either([number, record(["cut": string, "word": string, "time": number])], "placeMusic: {cut: \"<left>|<right>\"}, {word: id} or seconds."),
        "parts": noted(list(string), "placeMusic: a library song's parts to play, like [\"Drums\", \"Bass\"]."), "from": either([number, Self.bars], "placeMusic: the moment of the song that plays at at, in its own seconds or bars ({bar: 9})."),
        "fit": either([bool, number, string], "placeMusic: play the song from its start to its own ending, joined between bars that sound alike to last from at to endOn (true), this many seconds, or to the end of the picture (\"cut\")."),
        "heard": noted(map(list(record(["start": number, "end": number], required: ["start", "end"]))), "parts: {part: [{start, end}]}, where each part is heard in cut seconds; [] for nowhere."),
    ])])
    /// What each edit argument is, in a line, on the argument itself: the editor reads these, not the catalog.
    static let argumentWords: [String: String] = [
        "note": "The note number this operation answers, when the batch answers several.",
        "assetID": "A take\u{2019}s id (direction_dailies), or a sound or image\u{2019}s.", "clipID": "A clip\u{2019}s id from direction_timeline.",
        "withAssetID": "replaceTake: the take to swap in.", "toClipID": "matchBalance: the clip to match.", "madeID": "placeMade, placeMusic: a made clip\u{2019}s id.",
        "graphic": "placeGraphic: the graphic\u{2019}s name, its folder in Graphics/.", "effectID": "setEffect, removeEffect: the id addEffect returned.",
        "effect": "addEffect: transform, pin, blend, mask, blur, sharpen, stabilize, filter.<kind> or shader.",
        "target": "addEffect, gain: a clip\u{2019}s id from direction_timeline, or a track (V2 for picture; A1, A2 for sound). Not the word clip.",
        "track": "A track: V1, V2\u{2026} for picture, A1, A2\u{2026} for sound. duck: the track it lowers.", "under": "duck: the track whose words it ducks under (A1).",
        "editPoint": "Where two clips meet: \"<left clip id>|<right clip id>\".", "cover": "cutaway: a clip id or an edit point to center over.",
        "lut": "cameraLUT: auto, none, or a .cube file\u{2019}s path.", "text": "duplicateSequence: the copy\u{2019}s name.",
        "edge": "trim: which end.", "lead": "splitEdit: which leads across the cut.", "snap": "split, trim, roll: land on the nearest blink, peak of action or pause in the take within 8 frames (direction_cut_points lists them); the result says where.", "alignOn": "replaceTake: how the new take lines up.",
        "follow": "reframe: what the frame follows, tracked by Direction.", "keepIn": "Where the face sits in the frame.",
        "frames": "Frames at the cut\u{2019}s rate. trim, roll, slip, slide, splitEdit: + is later or longer, \u{2212} earlier or shorter. transition: its length.",
        "in": "fade: frames of fade in.", "out": "fade: frames of fade out.", "layer": "The layer: 0 is V1, 1 is V2.",
        "audioTrackID": "audio: the take\u{2019}s sound track id (direction_inspect).", "width": "format, duplicateSequence: width in pixels.", "height": "format, duplicateSequence: height in pixels.",
        "ripple": "Close the gap it leaves (removeRange and trim: true unless false).", "aboveLook": "placeGraphic: drawn over the look (true unless false).",
        "rate": "speed: 0.1\u{2013}8; 2 plays twice as fast.", "speed": "An older name for rate.",
        "seconds": "How long: freeze\u{2019}s hold, placeGraphic\u{2019}s length, a cutaway without sourceRange, zoomThrough\u{2019}s push.",
        "scale": "reframe and moves: 1 is the shot as framed, 1.2 a fifth closer.", "x": "reframe: across, a fraction of the frame (0 is centered).", "y": "reframe: up and down, a fraction of the frame (0 is centered).",
        "exposure": "balance: \u{2212}5 to 5 stops.", "contrast": "balance: 0\u{2013}4, 1 as shot.", "saturation": "balance: 0\u{2013}3, 1 as shot.", "temperature": "balance: \u{2212}3000 to 3000, warmer up.", "tint": "balance: \u{2212}100 to 100.",
        "longerThan": "tightenPauses: only pauses longer than this, in seconds.",
        "dB": "gain: the level, \u{2212}96 to 24 dB (it sets the level; it doesn\u{2019}t add). duck: how far under.", "attack": "duck: seconds to go down.", "release": "duck: seconds to come back.",
        "lufs": "loudness: the target in LUFS (Settings \u{203A} Cutting\u{2019}s unless given).", "truePeak": "loudness: the ceiling no peak passes, in dBTP (\u{2212}1 unless given).",
        "wordsAtATime": "captions: the most words on screen at once (the style\u{2019}s, or 7 wide and 4 tall).",
        "wordIDs": "removeWords: word ids from direction_transcript.", "params": "An effect\u{2019}s or transition\u{2019}s settings; direction_edit_catalog with op names them.",
        "keys": "{param: [{t, v, ease?}]}, t in cut seconds.", "grade": "A whole balance.", "framing": "A whole framing.", "frameRate": "format: the cut\u{2019}s rate.",
    ]
    private static let describedOperation: JSONValue = {
        guard case .object(var o) = operation, case .object(var properties) = o["properties"] ?? .null else { return operation }
        for (key, words) in argumentWords { if let p = properties[key], p["description"] == .null { properties[key] = noted(p, words) } }
        o["properties"] = .object(properties)
        return .object(o)
    }()
    private static let batchFields: [String: JSONValue] = ["baseEditRevision": integer, "sequenceID": string, "idempotencyKey": string, "summary": string, "notes": list(integer), "validateOnly": bool, "measure": bool, "operations": list(describedOperation)]
    // What the editor sends inside a directing call, field by field, so it doesn't guess from the words and
    // Direction can say which field is wrong before anything runs.
    private static let sceneInput = record(["id": string, "number": integer, "title": string, "setups": list(record(["code": string, "description": string], required: ["code", "description"]))], required: ["number", "title"])
    private static let takeInput = record(["assetID": string, "sceneID": string, "sceneNumber": integer, "setupCode": string, "code": string, "caption": string, "suggestion": string,
                                           "guessSceneNumber": integer, "flags": list(string), "unusable": bool], required: ["assetID"])
    private static let choiceInput = record(["id": string, "label": string, "detail": string, "assetID": string, "recommended": bool], required: ["label"])
    private static let answerInput = record([
        "noteID": string, "summary": string, "delta": string, "start": number, "end": number, "preferred": string, "unasked": bool, "kind": strings(NoteKind.allCases.map(\.rawValue)),
        "options": list(record(["label": strings(["A", "B"]), "summary": string, "revision": integer, "cutID": string, "delta": string], required: ["label", "summary"])),
        "rule": record(["text": string, "area": strings(StyleRule.areas.map(\.id)), "scope": strings(["style", "house"]), "replaces": list(string)], required: ["text"]),
    ], required: ["summary"])
    private static let readBackLine = record(["noteID": string, "plan": string, "delta": noted(string, "The change in a few characters, shown beside the plan: \u{2212}4.2 s, 1.6\u{00D7}, \u{2212}3 dB, crop. Words about it go in plan or detail."), "twoWays": bool, "conflictWithNoteID": string, "following": string,
                                              "range": noted(record(["start": number, "end": number], required: ["start", "end"]), "Where the two notes overlap, {start, end} in the cut's seconds."), "detail": string, "cantYet": string], required: ["noteID", "plan"])
    private static let finishingItem = record(["id": string, "title": string, "detail": string, "state": strings(["todo", "working", "done", "needsYou", "blocked"]),
                                               "by": list(strings(["editor", "you"])), "progress": fraction], required: ["id"])
    private static let transcript = record(["assetID": string, "audioTrackID": integer, "language": string, "provider": string, "words": list(record(["id": string, "text": string, "range": range], required: ["id", "text", "range"]))], required: ["assetID", "audioTrackID", "language", "provider", "words"])
    static func definition(_ name: String, _ description: String, _ properties: [String: JSONValue] = [:], required: [String] = [], readOnly: Bool = true) -> ToolDefinition {
        .init(name: name, description: description, inputSchema: .object(["type": .string("object"), "properties": .object(properties), "required": .array(required.map(JSONValue.string)), "additionalProperties": .bool(false)]), readOnly: readOnly)
    }
    public static let definitions: [ToolDefinition] = (rawDefinitions + directingDefinitions + phase2Definitions).map { definition in
        var result = definition
        guard case .object(var schema) = result.inputSchema, case .object(var properties) = schema["properties"] else { return result }
        // The older {batch: {…}} takes the same fields; it's checked as it runs, so its shape isn't listed twice.
        if definition.name == "direction_edit" { properties.merge(batchFields) { _, b in b }; properties["batch"] = noted(object, "Older: the same fields inside batch, as {batch: {baseEditRevision, operations, …}}. Send them at the top level.") }
        if definition.name == "direction_import_transcript" { properties["transcript"] = transcript }
        if definition.name == "direction_add_comment" { properties["region"] = record(["x": number, "y": number, "width": number, "height": number], required: ["x", "y", "width", "height"]) }
        if !["direction_projects", "direction_create_project", "direction_open_project"].contains(definition.name) {
            properties["projectPath"] = .object(["type": .string("string"), "description": .string("Absolute .direction project path; required unless server was launched with --project.")])
        }
        schema["properties"] = .object(properties); result.inputSchema = .object(schema)
        return result
    }
